    private void init() throws IOException {
        File f = new File(file);
        RandomAccessFileReader in = new RandomAccessFileReader(f);
        SimpleDateFormat dateformat = new SimpleDateFormat(DATE_FORMAT);
        Pattern idp = Pattern.compile("\\[myid:(\\d+)\\]");
        long lastFp = in.getPosition();
        String line = in.readLine();
        Matcher m = null;
        // if we have read data from the file, and it matches the timep pattern
        if ((line != null) && (m = timep.matcher(line)).lookingAt()) {
            starttime = timestampFromText(dateformat, m.group(1));
        } else {
            throw new IOException("Invalid log format. First line doesn't start with time");
        }
        /*
	  Count number of log entries. Any line starting with a timestamp counts as an entry
	*/

        String lastentry = line;

        try {
            while (line != null) {
                m = timep.matcher(line);

                if (m.lookingAt()) {
                    if (size % skipN == 0) {
                        long time = timestampFromText(dateformat, m.group(1));
                        skiplist.addMark(time, lastFp, size);
                    }

                    size++;
                    lastentry = line;
                } 

                if (serverid == 0 && (m = idp.matcher(line)).find()) {
                    serverid = Integer.valueOf(m.group(1));
                }

                lastFp = in.getPosition();
                line = in.readLine();
            }
        } catch (EOFException eof) {
        // ignore, simply end of file, though really (line!=null) should have caught this
        } finally {
            in.close();
        }

        m = timep.matcher(lastentry);

        if (m.lookingAt()) {
            endtime = timestampFromText(dateformat, m.group(1));
        } else {
            throw new IOException("Invalid log format. Last line doesn't start with time");
        }
    }

void drainFused() {
    int missed = 1;

    for (;;) {
        if (disposed) {
            return;
        }

        boolean d = done;
        Throwable ex = error;
        if (!delayError && d && ex != null) {
            disposed = true;

            downstream.onError(error);

            worker.dispose();

            return;
        }
        downstream.onNext(null);
        if (d) {
            disposed = true;

            ex = error;
            if (ex != null) {
                downstream.onError(ex);
            } else {
                downstream.onComplete();
            }
            worker.dispose();

            return;
        }
        missed = addAndGet(-missed);
        if (missed == 0) {
            break;
        }
    }
}

private ApiResponse processAsyncExecRequest(ApiRequest apiRequest, Session session) {
    String commandLine = apiRequest.getCommand();
    Map<String, Object> body = new TreeMap<String, Object>();
    body.put("command", commandLine);
    ApiResponse response = new ApiResponse();
    response.setSessionId(session.getSessionId()).setBody(body);

    if (!session.tryLock()) {
        response.setState(ApiState.REFUSED).setMessage("Another command is executing.");

        return response;
    }
    int lock = session.getLock();
    try {
        Job foregroundJob = session.getForegroundJob();
        if (foregroundJob != null) {
            response.setState(ApiState.REFUSED).setMessage("Another job is running.");

            logger.info("Another job is running, jobId: {}", foregroundJob.id());
            return response;
        }
        //create job
        Job job = this.createJob(commandLine, session, session.getResultDistributor());
        body.put("jobId", job.id());
        body.put("jobStatus", job.status());
        response.setState(ApiState.SCHEDULED);
        //add command before exec job
        CommandRequestModel commandRequestModel = new CommandRequestModel(commandLine, response.getState());
        commandRequestModel.setJobId(job.id());
        SharingResultDistributor resultDistributor = session.getResultDistributor();
        if (resultDistributor != null) {
            resultDistributor.appendResult(commandRequestModel);
        }
        session.setForegroundJob(job);
        updateSessionInputStatus(session, InputStatus.ALLOW_INTERRUPT);
        //run job
        job.run();
        return response;
    } catch (Throwable e) {
        logger.error("Async exec command failed:" + e.getMessage() + ", command:" + commandLine, e);

        response.setState(ApiState.FAILED).setMessage("Async exec command failed:" + e.getMessage());
        CommandRequestModel commandRequestModel = new CommandRequestModel(commandLine, response.getState(), response.getMessage());

        session.getResultDistributor().appendResult(commandRequestModel);
        return response;
    } finally {
        if (session.getLock() == lock) {
            session.unLock();
        }
    }
}

private void flushAuxiliar(long amount) throws IOException {
    if (aux.length < 1) {
        return;
    }
    out.flush();
    aux.flush();

    boolean underflow = aux.offset < aux.length || out.offset < out.length;
    byte[] buffer = new byte[COPY_BUFFER_SIZE];
    aux.target.seek(0);
    out.target.seek(out.length);

    long length = amount;

    while (length > 0) {
        int read = (int) Math.min(length, Integer.MAX_VALUE);
        read = aux.target.read(buffer, 0, Math.min(read, buffer.length));

        if (read < 1) {
            amount -= length;
            break;
        }
        out.writeProof(buffer, read);
        length -= read;
    }

    if (!underflow) {
        out.offset += amount;
        aux.offset -= amount;
    } else {
        if (out.offset < out.length) {
            aux.offset = 0;
        } else {
            // calculate the aux underflow pointer
            if (aux.offset >= amount) {
                aux.offset -= amount;
                out.offset = out.length + amount;
            } else {
                out.offset += aux.offset;
                aux.offset = 0;
                out.target.seek(out.offset);
            } 
        } 
    } 

    out.length += amount;

    if (out.length > maxLengthKnown) {
        maxLengthKnown = out.length;
    }

    if (amount < aux.length) {
        // move the excess data to the beginning of the file
        long readOffset = amount;
        long writeOffset = 0;
        aux.length -= amount;
        length = aux.length;

        while (length > 0) {
            int read = (int) Math.min(length, Integer.MAX_VALUE);
            read = aux.target.read(buffer, 0, Math.min(read, buffer.length));
            aux.target.seek(writeOffset);
            aux.writeProof(buffer, read);
            writeOffset += read;
            readOffset += read;
            length -= read;
            aux.target.seek(readOffset);
        }

        aux.target.setLength(aux.length);
        return;
    }

    if (aux.length > THRESHOLD_AUX_LENGTH) {
        aux.target.setLength(THRESHOLD_AUX_LENGTH); // or setLength(0);

    }
    aux.reset();
}

private JsonNode validateLicense(String licenseKey, String machineFingerprint, LicenseContext context) throws Exception {
    String requestBody = String.format("{\"meta\":{\"key\":\"%s\",\"scope\":{\"fingerprint\":\"%s\"}}}", licenseKey, machineFingerprint);

    HttpRequest request = HttpRequest.newBuilder()
    .uri(URI.create(BASE_URL + "/" + ACCOUNT_ID
     + "/licenses/actions/validate-key"))
    .header("Content-Type", "application/vnd.api+json")
    .header("Accept", "application/vnd.api+json")
    // .header("Authorization", "License " + licenseKey)
    .POST(HttpRequest.BodyPublishers.ofString(requestBody)).build();

    HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
    log.debug("ValidateLicenseResponse body: {}", response.body());
    JsonNode jsonResponse = objectMapper.readTree(response.body());

    if (response.statusCode() != 200) {
        log.error("Error validating license. Status code: {}", response.statusCode());
    } else {


        JsonNode metaNode = jsonResponse.path("meta");
        boolean isValid = metaNode.path("valid").asBoolean();
        String detail = metaNode.path("detail").asText();
        String code = metaNode.path("code").asText();
        log.info("License validity: {}", isValid);
        log.info("Validation detail: {}", detail);
        log.info("Validation code: {}", code);
        // Check if the license itself has floating attribute
        JsonNode licenseAttrs = jsonResponse.path("data").path("attributes");
        if (!licenseAttrs.isMissingNode()) {
            context.isFloatingLicense = licenseAttrs.path("floating").asBoolean(false);
            context.maxMachines = licenseAttrs.path("maxMachines").asInt(1);
            log.info("License floating (from license): {}, maxMachines: {}", context.isFloatingLicense, context.maxMachines);
        }

        // Also check the policy for floating license support if included
        JsonNode includedNode = jsonResponse.path("included");
        JsonNode policyNode = null;
        if (includedNode.isArray()) {

            for (JsonNode node : includedNode) {
                if ("policies".equals(node.path("type").asText())) {
                    policyNode = node;
                    break;
                }
            }
        }

        if (policyNode != null) {
            // Check if this is a floating license from policy
            boolean policyFloating = policyNode.path("attributes").path("floating").asBoolean(false);

            int policyMaxMachines = policyNode.path("attributes").path("maxMachines").asInt(1);
            // Policy takes precedence over license attributes
            if (policyFloating) {
                context.isFloatingLicense = true;
                context.maxMachines = policyMaxMachines;
            }

            log.info("License floating (from policy): {}, maxMachines: {}", context.isFloatingLicense, context.maxMachines);
        }

        // Extract user count, default to 1 if not specified
        int users = jsonResponse.path("data").path("attributes").path("metadata").path("users").asInt(1);
        applicationProperties.getPremium().setMaxUsers(users);
        // Extract isEnterprise flag
        context.isEnterpriseLicense = jsonResponse.path("data").path("attributes").path("metadata").path("isEnterprise").asBoolean(false);
        log.debug(applicationProperties.toString());
    } 

    return jsonResponse;
}

void drainLoop() {
    int missed = 1;
    JoinInnerSubscriber<T>[] s = this.subscribers;
    int n = s.length;
    Subscriber<? super T> a = this.downstream;

    for (;;) {
        long r = requested.get();
        long e = 0;
        middle : 
        while (e != r) {
            if (cancelled) {
                cleanup();
                return;
            }

            Throwable ex = errors.get();
            if (ex != null) {
                cleanup();
                a.onError(ex);
                return;
            }

            boolean d = done.get() == 0;
            boolean empty = true;
            for (int i = 0; i < s.length; i++) {
                JoinInnerSubscriber<T> inner = s[i];
                SimplePlainQueue<T> q = inner.queue;
                if (q != null) {
                    T v = q.poll();
                    if (v != null) {
                        empty = false;
                        a.onNext(v);
                        inner.requestOne();

                        if (++e == r) {
                            break middle;
                        }
                    }
                }
            }

            if (d && empty) {
                a.onComplete();
                return;
            }
            if (empty) {
                break;
            }
        }


        if (e == r) {
            if (cancelled) {
                cleanup();
                return;
            }

            Throwable ex = errors.get();
            if (ex != null) {
                cleanup();
                a.onError(ex);
                return;
            }

            boolean d = done.get() == 0;
            boolean empty = true;
            for (int i = 0; i < n; i++) {
                JoinInnerSubscriber<T> inner = s[i];
                SimpleQueue<T> q = inner.queue;
                if (q != null && !q.isEmpty()) {
                    empty = false;
                    break;
                }
            }

            if (d && empty) {
                a.onComplete();
                return;
            }
        }
        if (e != 0) {
            BackpressureHelper.produced(requested, e);
        }
        missed = addAndGet(-missed);

        if (missed == 0) {
            break;
        }
    }
}

public void schedule(WorkRequest workRequest, long id) {
    if (stopped) {
        workRequest.cleanup();
        return;
    }
    ScheduledWorkRequest scheduledWorkRequest = new ScheduledWorkRequest(workRequest);
    // If we have a worker thread pool, use that; otherwise, do the work
    // directly.
    int size = workers.size();
    if (size > 0) {
        try {
            // make sure to map negative ids as well to [0, size-1]
            int workerNum = ((int) (id % size) + size) % size;
            ExecutorService worker = workers.get(workerNum);
            worker.execute(scheduledWorkRequest);
        } catch (RejectedExecutionException e) {
            LOG.warn("ExecutorService rejected execution", e);
            workRequest.cleanup();
        }
    } else {
        // When there is no worker thread pool, do the work directly
        // and wait for its completion
        scheduledWorkRequest.run();
    }
}

private static void sanitizeHtmlFilesInZip(Path zipFilePath, boolean disableSanitize, TempFileManager tempFileManager) throws IOException {
    try (TempDirectory tempUnzippedDir = new TempDirectory(tempFileManager)) {
        try (ZipInputStream zipIn = 
        ZipSecurity.createHardenedInputStream(
        new ByteArrayInputStream(Files.readAllBytes(zipFilePath)))) {

            ZipEntry entry = zipIn.getNextEntry();
            while (entry != null) {
                Path filePath = tempUnzippedDir.getPath().resolve(sanitizeZipFilename(entry.getName()));
                if (!entry.isDirectory()) {
                    Files.createDirectories(filePath.getParent());
                    if (!(entry.getName().toLowerCase().endsWith(".html") || entry.getName().toLowerCase().endsWith(".htm"))) {
                        Files.copy(zipIn, filePath);
                    } else {
                        String content = new String(zipIn.readAllBytes(), StandardCharsets.UTF_8);

                        String sanitizedContent = sanitizeHtmlContent(content, disableSanitize);
                        Files.write(filePath, sanitizedContent.getBytes(StandardCharsets.UTF_8));
                    } 

                }

                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }

        // Repack the sanitized files
        zipDirectory(tempUnzippedDir.getPath(), zipFilePath);
    } 
// tempUnzippedDir auto-cleaned
}

public static FieldVO[] getFields(Class clazz, Integer expand) {
    Field[] fields = clazz.getDeclaredFields();
    if (fields.length == 0) {
        return new FieldVO[0];
    }
    List<FieldVO> list = new ArrayList<FieldVO>(fields.length);

    for (Field field:fields) {
        FieldVO fieldVO = new FieldVO();
        fieldVO.setName(field.getName());
        fieldVO.setType(StringUtils.classname(field.getType()));

        fieldVO.setModifier(StringUtils.modifier(field.getModifiers(), ','));

        fieldVO.setAnnotations(getAnnotations(field.getAnnotations()));

        if (! (Modifier.isStatic(field.getModifiers()))) {
            fieldVO.setStatic(false);
        } else {
            fieldVO.setStatic(true);
            fieldVO.setValue(new ObjectVO(getFieldValue(field), expand));
        } 
        list.add(fieldVO);
    }

    return list.toArray(new FieldVO[0]);
}
